PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS colleges(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS classes(id INTEGER PRIMARY KEY,college_id INTEGER NOT NULL REFERENCES colleges(id),name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,game_id TEXT NOT NULL UNIQUE,ign TEXT NOT NULL,class_id INTEGER NOT NULL REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,student_id INTEGER UNIQUE REFERENCES students(id),role TEXT NOT NULL CHECK(role IN ('admin','organizer','referee','student')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS role_permissions(role TEXT NOT NULL,permission TEXT NOT NULL,PRIMARY KEY(role,permission));
CREATE TABLE IF NOT EXISTS teams(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,tag TEXT NOT NULL,captain_id INTEGER NOT NULL REFERENCES students(id),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS memberships(id INTEGER PRIMARY KEY,team_id INTEGER NOT NULL REFERENCES teams(id),student_id INTEGER NOT NULL REFERENCES students(id),status TEXT NOT NULL CHECK(status IN('invited','accepted','declined','left')),position TEXT NOT NULL DEFAULT '',UNIQUE(team_id,student_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_current_team ON memberships(student_id) WHERE status='accepted';
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,name TEXT NOT NULL,format TEXT NOT NULL CHECK(format IN('knockout','roundrobin')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','locked','live','finished')),opens TEXT NOT NULL,closes TEXT NOT NULL,reserve_max INTEGER NOT NULL DEFAULT 2 CHECK(reserve_max BETWEEN 0 AND 2),win_points INTEGER NOT NULL DEFAULT 3,loss_points INTEGER NOT NULL DEFAULT 0,pool INTEGER NOT NULL DEFAULT 0 CHECK(pool>=0),CHECK(opens<closes),CHECK(win_points>loss_points AND loss_points>=0));
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES events(id),team_id INTEGER NOT NULL REFERENCES teams(id),status TEXT NOT NULL CHECK(status IN('pending','approved','rejected','withdrawn')),reason TEXT NOT NULL DEFAULT '',reviewer_id INTEGER REFERENCES users(id),created TEXT NOT NULL,UNIQUE(event_id,team_id));
CREATE TABLE IF NOT EXISTS rosters(id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES entries(id),event_id INTEGER NOT NULL REFERENCES events(id),student_id INTEGER NOT NULL REFERENCES students(id),starter INTEGER NOT NULL CHECK(starter IN(0,1)),holding INTEGER NOT NULL CHECK(holding IN(0,1)),UNIQUE(entry_id,student_id));
CREATE UNIQUE INDEX IF NOT EXISTS no_cross_team ON rosters(event_id,student_id) WHERE holding=1;
CREATE TABLE IF NOT EXISTS rounds(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES events(id),number INTEGER NOT NULL,name TEXT NOT NULL,UNIQUE(event_id,number));
CREATE TABLE IF NOT EXISTS matches(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES events(id),round_id INTEGER NOT NULL REFERENCES rounds(id),slot INTEGER NOT NULL,team_a INTEGER REFERENCES teams(id),team_b INTEGER REFERENCES teams(id),best_of INTEGER NOT NULL CHECK(best_of IN(3,5)),starts TEXT,ends TEXT,referee_id INTEGER REFERENCES users(id),state TEXT NOT NULL DEFAULT 'scheduled' CHECK(state IN('scheduled','live','finished','bye')),winner_id INTEGER REFERENCES teams(id),next_id INTEGER REFERENCES matches(id),next_slot TEXT CHECK(next_slot IN('a','b')),version INTEGER NOT NULL DEFAULT 1,CHECK(team_a IS NULL OR team_b IS NULL OR team_a<>team_b),CHECK(starts IS NULL OR ends IS NULL OR starts<ends),UNIQUE(round_id,slot));
CREATE UNIQUE INDEX IF NOT EXISTS unique_target ON matches(next_id,next_slot) WHERE next_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS event_schedule ON matches(event_id,starts);
CREATE TABLE IF NOT EXISTS heroes(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY,match_id INTEGER NOT NULL REFERENCES matches(id),number INTEGER NOT NULL CHECK(number>0),winner_id INTEGER NOT NULL REFERENCES teams(id),duration INTEGER NOT NULL CHECK(duration>0),exception_reason TEXT NOT NULL DEFAULT '',author_id INTEGER NOT NULL REFERENCES users(id),UNIQUE(match_id,number));
CREATE TABLE IF NOT EXISTS stats(game_id INTEGER NOT NULL REFERENCES games(id),student_id INTEGER NOT NULL REFERENCES students(id),team_id INTEGER NOT NULL REFERENCES teams(id),hero_id INTEGER NOT NULL REFERENCES heroes(id),kills INTEGER NOT NULL CHECK(kills>=0),deaths INTEGER NOT NULL CHECK(deaths>=0),assists INTEGER NOT NULL CHECK(assists>=0),gold INTEGER CHECK(gold>=0),PRIMARY KEY(game_id,student_id));
CREATE TABLE IF NOT EXISTS prizes(event_id INTEGER NOT NULL REFERENCES events(id),rank INTEGER NOT NULL CHECK(rank>0),amount INTEGER NOT NULL CHECK(amount>=0),PRIMARY KEY(event_id,rank));
CREATE TABLE IF NOT EXISTS final_results(event_id INTEGER NOT NULL REFERENCES events(id),team_id INTEGER NOT NULL REFERENCES teams(id),rank INTEGER NOT NULL CHECK(rank>0),amount INTEGER NOT NULL CHECK(amount>=0),reason TEXT NOT NULL DEFAULT '',author_id INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,PRIMARY KEY(event_id,team_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL,until REAL NOT NULL);
